package ir.ghiyas.alimaa.domain.strategy

import com.ionspin.kotlin.bignum.decimal.BigDecimal
import com.ionspin.kotlin.bignum.decimal.DecimalMode
import ir.ghiyas.alimaa.domain.models.ResultItem
import ir.ghiyas.alimaa.domain.models.WalnutUnit

object BarkatCalculationStrategy : DefaultCalculationStrategy {
    override val title: String = "برکت (۹ حبه)"
    override val isGlobalMacro: Boolean = false // چون مرحله کشاورزی را خودش انجام می‌دهد اما ماکروی یکپارچه دو شریک نیست

    override fun calculate(input: DistributionInput): List<ResultItem> {
        val pool = BigDecimal.fromDouble(input.poolAmount.value)
        if (pool.compareTo(BigDecimal.ZERO) <= 0) return emptyList()

        val decimalMode = DecimalMode(decimalPrecision = 15)

        // فرمول ۱: ۴۸ قیاس از ۲۱۶ قیاس (معادل ۲/۹ کل بار)
        val factor48 = BigDecimal.fromInt(48)
        val factor216 = BigDecimal.fromInt(216)

        val x = pool.multiply(factor48).divide(factor216, decimalMode)
        
        // تقسیم بر ۲ برای نواب و متغیر کشاورزی برکت-کرامت
        val halfX = x.divide(BigDecimal.fromInt(2), decimalMode)

        val navvabShare = halfX
        var agriBK = halfX

        // فرمول ۲: باقیمانده (۱۶۸ قیاس از ۲۱۶)
        val r2 = pool.subtract(x)

        // باقیمانده تقسیم بر ۳ و افزودن به کشاورزی
        val t = r2.divide(BigDecimal.fromInt(3), decimalMode)
        agriBK = agriBK.add(t)

        // فرمول ۳: باقیمانده جدید (دو سومِ R2) تقسیم بر ۳.۵
        val r3 = r2.subtract(t)
        val s = r3.divide(BigDecimal.parseString("3.5"), decimalMode)

        // دو سهم دختر (۰.۵)
        val marymShare = s.multiply(BigDecimal.parseString("0.5"))
        val hajiNesaShare = s.multiply(BigDecimal.parseString("0.5"))

        // دو و نیم سهم باقیمانده (۱ برای برکت، ۱.۵ برای کرامت)
        val barkatShare = s.multiply(BigDecimal.fromInt(1))
        val keramatShare = s.multiply(BigDecimal.parseString("1.5"))

        // تقسیم متغیر کشاورزی برکت-کرامت به دو قسمت مساوی
        val agriB = agriBK.divide(BigDecimal.fromInt(2), decimalMode)
        val agriK = agriBK.divide(BigDecimal.fromInt(2), decimalMode)

        // جمع‌بندی سهم خالص هر برادر با سهم کشاورزی‌اش
        val totalBarkat = barkatShare.add(agriB)
        val totalKeramat = keramatShare.add(agriK)

        // تسهیم درونی وارثین
        val perBarkat = totalBarkat.divide(BigDecimal.fromInt(5), decimalMode)
        val baseKeramatBoy = totalKeramat.divide(BigDecimal.parseString("4.5"), decimalMode)
        val baseKeramatGirl = baseKeramatBoy.divide(BigDecimal.fromInt(2), decimalMode)

        return listOf(
            ResultItem("سهم نواب", WalnutUnit(navvabShare.doubleValue(false))),
            ResultItem("سهم مریم", WalnutUnit(marymShare.doubleValue(false))),
            ResultItem("سهم حاجی نساء", WalnutUnit(hajiNesaShare.doubleValue(false))),
            ResultItem("سهم کلی برکت (کشاورزی و سهم)", WalnutUnit(totalBarkat.doubleValue(false))),
            ResultItem("سهم هر برکتی", WalnutUnit(perBarkat.doubleValue(false))),
            ResultItem("سهم کلی کرامت (کشاورزی و سهم)", WalnutUnit(totalKeramat.doubleValue(false))),
            ResultItem("سهم هر پسر کرامت", WalnutUnit(baseKeramatBoy.doubleValue(false))),
            ResultItem("سهم هر دختر کرامت", WalnutUnit(baseKeramatGirl.doubleValue(false)))
        )
    }
}
